def download(self):
    """ Main download function """
    click.echo("===============================================================")
    if config.get("verbose"):
        click.echo(str(self))
    else:
        click.echo(" | ".join(self.row))

    self.download_song()
    if config.get("lyrics"):
        self.download_lyrics()
    if config.get("cover"):
        self.download_cover()

    click.echo("===============================================================\n")

def _save_lyrics_text(self):
    with open(self.lyrics_fullname, "w") as f:
        f.write(self.lyrics_text)
        click.echo(
            _(" :: Saved to: {outfile}").format(
                outfile=colorize(self.lyrics_fullname, "highlight")
            )
        )

def download_lyrics(self):
    row_data = {"csrf_token": "", "id": self.id, "lv": -1, "tv": -1}
    data = NeteaseApi.encrypted_request(row_data)

    self.lyrics_text = (
        NeteaseApi.request(
            "https://music.163.com/weapi/song/lyric", method="POST", data=data
        )
        .get("lrc", {})
        .get("lyric", "")
    )

    if self.lyrics_text:
        super(NeteaseSong, self)._save_lyrics_text()

